WITH parsed AS (SELECT id, service, level, context, context['version'] AS version, COALESCE(context['trace'], 'direct') AS trace_or_default, SIZE(context) AS num_context, ARRAY_CONTAINS(MAP_KEYS(context), 'region') AS has_region, context['region'] AS region FROM app_logs WHERE level = 'INFO') SELECT level, AVG(num_context) FILTER (WHERE level = 'DEBUG') AS debug_avg_num_context, PERCENTILE_APPROX(num_context, 0.5) AS num_context_p50, COUNT(CASE WHEN level = 'INFO' THEN 1 END) AS info_count, SUM(CASE WHEN service = 'checkout' THEN num_context ELSE 0 END) AS checkout_num_context, SUM(num_context) FILTER (WHERE service = 'auth') AS auth_total_num_context FROM parsed GROUP BY 1 HAVING SUM(num_context) FILTER (WHERE service = 'auth') > 0;
